import{z as B,x as n,o as e,c as A,q as o,j as t,D as E,d as i,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"彗差","description":"","frontmatter":{"title":"彗差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/coma-aberration.md","filePath":"litho/coma-aberration.md","lastUpdated":1791413859000}'),p={name:"litho/coma-aberration.md"};function h(d,a,c,m,D,_){const r=n("Mermaid");return e(),A("div",null,[a[2]||(a[2]=o('<h1 id="彗差" tabindex="-1">彗差 <a class="header-anchor" href="#彗差" aria-label="Permalink to &quot;彗差&quot;">​</a></h1><div class="epigraph"><p>球差还保持圆对称；初级彗差随视场线性出现，波前带 $\\rho^3\\cos\\phi$，点扩散拖出彗尾——左右边的 NILS 不再相等。</p><footer>—— Born &amp; Wolf, Principles of Optics 对初级彗差的讨论</footer></div><p><a href="/litho/spherical-aberration">上一课</a>把轴上 \\(\\rho^4\\) 钉成球差。缺口是：<strong>离轴之后最先到来的不对称项</strong>。像散与场曲留给<a href="/litho/astigmatism-field">下一课</a>。不要把彗尾写成又一种球差，也不要引用未公开的狭缝彗差表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Seidel 初级彗差（\\(S_{II}\\)）对轴上点物为零，随视场半径涨，孔径上是奇数次的 \\(\\rho^3\\cos\\phi\\)（或 \\(\\sin\\phi\\)，视子午方向）。几何图像是彗星状：主光线交点旁拖一串由不同环带造成的圆斑。光刻里这表现为线的一边陡、一边缓，以及套刻标记左右臂不对称。缺口因此是这根<strong>奇对称</strong>，而不是再配平一次 \\(\\rho^4\\)。</p><p>正弦条件正是为压低彗差而设。上一课的齐明与本课的彗差是同一设计故事的两面；残差仍进 Zernike（Fringe 里低阶彗差常在 \\(Z_7\\)、\\(Z_8\\) 一带，约定仍须声明）。</p><h3 id="彗差不是远心" tabindex="-1">彗差不是远心 <a class="header-anchor" href="#彗差不是远心" aria-label="Permalink to &quot;彗差不是远心&quot;">​</a></h3><p>远心误差让质心随 \\(\\Delta z\\) 线性搬家，最佳焦距上可以很小。彗差在最佳焦距上已经让核带尾巴，离焦再叠加。把通过焦点的套刻扇形全部写成 \\(\\alpha\\Delta z\\)，会漏掉即使 \\(z=0\\) 也在的左右 CD 差。</p><p><span class="marginnote">扫描狭缝两端视场最大，彗差往往在狭缝边缘最明显。报「本台镜头的彗差」必须声明场点；OPC 用单一核等于忽略这根向量。</span></p><p><span class="marginnote">术语翻译：彗差的&quot;彗&quot;就是彗星的彗——点物的像不再是一个圆斑，而是拖着一条逐渐变宽的尾巴。波前 \\(\\rho^3\\cos\\phi\\) 翻译成大白话：光瞳上离中心越远、且偏向某个固定方向的地方，相位错得越多，而且错法是&quot;单边&quot;的，左边和右边不对称。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 \\(W\\propto H\\rho^3\\cos\\phi\\) 乘进光瞳（\\(H\\) 为视场）。相干核沿彗差轴不对称：卷积后，孤立线两端一个变钝、一个相对保留，密栅两条边的 ILS 可以一高一低。部分相干不消除奇对称，只是把许多源点的彗尾平均——源若也离轴，有效彗差与照明质心纠缠。</p><p>Born &amp; Wolf 用光扇图读彗差：子午光束的交点相对主光线偏移。计算光刻不必画光扇，但读 Bossung 时要分左右边、分视场。</p><h3 id="套刻标记比密线更早就范" tabindex="-1">套刻标记比密线更早就范 <a class="header-anchor" href="#套刻标记比密线更早就范" aria-label="Permalink to &quot;套刻标记比密线更早就范&quot;">​</a></h3><p>盒中盒、条形标记的边缘走的是中频，核的尾巴把一边的阈值等高线推移，读出假套刻。真套刻（器件层对准）与标记层若空间频率不同，彗差造成的偏置对不上。这是光学像差进套刻预算的一条，不是工件台。</p><p><span class="marginnote">奇数像差对左右边的剂量灵敏度相反：一边 NILS 掉时另一边可能仍陡。只报平均 CD 会把彗差藏进「看起来还行」。</span></p>',16)),(e(),t(s,null,{default:E(()=>[l(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20SA%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%90%83%E5%B7%AE%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20COMA%5B%22%E5%88%9D%E7%BA%A7%E5%BD%97%E5%B7%AE%20%CF%81%C2%B3%20cos%CF%86%22%5D%0A%20%20FLD%5B%22%E8%A7%86%E5%9C%BA%20H%22%5D%20--%3E%20COMA%0A%20%20COMA%20--%3E%20TAIL%5B%22%E5%BD%97%E5%B0%BE%E6%A0%B8%22%5D%0A%20%20TAIL%20--%3E%20NILS%5B%22%E5%B7%A6%E5%8F%B3%20NILS%20%E4%B8%8D%E7%AD%89%22%5D%0A%20%20TAIL%20--%3E%20OV%5B%22%E6%A0%87%E8%AE%B0%E5%B7%A6%E5%8F%B3%E5%81%8F%E7%BD%AE%22%5D%0A%20%20NILS%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%83%8F%E6%95%A3%E5%8A%88%20H%2FV%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">直觉类比：把镜头想成一圈圈同心环带，每圈各自成一个略歪的像。球差是各圈的像同心地胖出去；彗差是各圈的像沿一个方向排成一串、越外圈偏得越远——叠起来就是那顶&quot;彗尾&quot;。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>奇数相位让脉冲响应失去中心对称。像面卷积把「哪一边先接到能量」固定下来，阈值模型给出定向的边位移。频率上，彗差对光瞳一边加权、另一边反向，对方向敏感的图形（水平 vs 垂直线）表现不同——但与像散的双焦线机制仍不同：彗差是三次、奇函数；像散是二次、\\(\\cos 2\\phi\\)。</p><p>Jones 两通道共用几何彗差。取向选择让某一组密线更走光瞳边缘，彗尾可以看起来像「偏振问题」；拆开看，相位仍是 \\(W\\)。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到左右不对称、线端定向缩短、标记假套刻，先问彗差（及场点），再问照明质心与掩模 3D。像散不要用彗尾去冒充。下一课的 H/V 最佳焦劈裂是另一项。</p><p><span class="marginnote">常见误区：初学者以为彗差要离焦才冒出来。实际上最佳焦面上彗尾已经在——&quot;随 \\(\\Delta z\\) 线性搬家&quot;的是远心误差。把套刻扇形全归给 \\(\\alpha\\Delta z\\)，就会漏掉 \\(z=0\\) 也存在的左右 CD 差。</span></p>',7)),(e(),t(s,null,{default:E(()=>[l(r,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22%E5%83%8F%E5%B7%AE%E7%9A%84%E5%AF%B9%E7%A7%B0%E6%80%A7%E8%B0%B1%E7%B3%BB%22%5D%20--%3E%20SA2%5B%22%E7%90%83%E5%B7%AE%20%CF%81%E2%81%B4%EF%BC%9A%E5%81%B6%E5%AF%B9%E7%A7%B0%E3%80%81%E8%BD%B4%E4%B8%8A%E5%B0%B1%E6%9C%89%22%5D%0A%20%20SYM%20--%3E%20CO2%5B%22%E5%BD%97%E5%B7%AE%20%CF%81%C2%B3%20cos%CF%86%EF%BC%9A%E5%A5%87%E5%AF%B9%E7%A7%B0%E3%80%81%E9%9A%8F%E8%A7%86%E5%9C%BA%E7%BA%BF%E6%80%A7%22%5D%0A%20%20SYM%20--%3E%20AS2%5B%22%E5%83%8F%E6%95%A3%20cos%202%CF%86%EF%BC%9A%E5%90%8E%E8%AF%BE%E3%80%81H%2FV%20%E5%8A%88%E8%A3%82%22%5D%0A%20%20SA2%20--%3E%20EFF1%5B%22%E5%9C%86%E6%96%91%E5%9D%87%E5%8C%80%E5%8F%98%E8%83%96%E3%80%81%E6%97%A0%E5%B7%A6%E5%8F%B3%E5%B7%AE%22%5D%0A%20%20CO2%20--%3E%20EFF2%5B%22%E5%8D%95%E8%BE%B9%E6%8B%96%E5%B0%BE%EF%BC%9A%E4%B8%80%E8%BE%B9%E9%99%A1%E4%B8%80%E8%BE%B9%E7%BC%93%22%5D%0A%20%20AS2%20--%3E%20EFF3%5B%22%E4%B8%A4%E4%B8%AA%E6%AD%A3%E4%BA%A4%E6%96%B9%E5%90%91%E7%84%A6%E8%B7%9D%E4%B8%8D%E5%90%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不含扫描平均把彗差扫成有效畸变的全部细节——狭缝积分会改有效系数，但不改 \\(\\rho^3\\cos\\phi\\) 的定义。禁止编造未公开的毫波数彗差；Born &amp; Wolf 的 Seidel 项与 Zernike 课的拟合接口已经够用。高阶彗差（\\(\\rho^5\\) 等）同样奇对称，截断后残差仍在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>初级彗差随视场线性出现，波前 \\(\\rho^3\\cos\\phi\\)，核带彗尾。</li><li>左右 NILS 与套刻标记对它最敏感；轴上球差没有这根不对称。</li><li>不是远心：最佳焦距上已经在。</li><li>必须报场点与 Zernike 约定。</li><li>H/V 焦线劈裂下一课。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',4))])}const C=B(p,[["render",h]]);export{F as __pageData,C as default};
